import argparse,asyncio,json,os,math,time
from pathlib import Path
from playwright.async_api import async_playwright
parser=argparse.ArgumentParser(description='Development-only IWER Quest integration checks; never installs an emulator in the application.')
parser.add_argument('--runtime',type=Path,required=True)
parser.add_argument('--output',type=Path,default=Path('/tmp/quest-validation'))
args=parser.parse_args()
ROOT=args.output
ROOT.mkdir(parents=True,exist_ok=True)
