  initial=await page.evaluate('xrStore.getState().origin.position.toArray()'); moved=False
  for yaw in [0,-0.7,0.7,1.2,-1.2]:
   await page.evaluate("yaw=>{device.controllers.left.position.set(-0.2,1.3,-0.3);device.controllers.left.quaternion.set(-0.258819*Math.cos(yaw/2),0.965926*Math.sin(yaw/2),0.258819*Math.sin(yaw/2),0.965926*Math.cos(yaw/2))}",yaw)
   await page.wait_for_timeout(900);await page.evaluate("device.controllers.left.updateButtonValue('trigger',1)");await page.wait_for_timeout(700);await page.evaluate("device.controllers.left.updateButtonValue('trigger',0)");await page.wait_for_timeout(1200)
