  await page.evaluate('device.controllers.right.position.x+=0.5');await page.wait_for_timeout(1200);await page.evaluate("device.controllers.right.updateButtonValue('squeeze',0)");await page.wait_for_timeout(1500)
  change=await page.evaluate("({before:beforeObject,after:sceneStore.getState().scene.objects.find(o=>o.id===objectId),pastDelta:sceneStore.getState().past.length-pastBefore})")
  print('Controller move:',change);assert abs(change['after']['position'][0]-change['before']['position'][0]-0.5)<0.05 and change['pastDelta']==1
  # Hand pinch path, not DOM events or R3F handler calls.
