  assert await page.evaluate("xrStore.getState().inputSourceStates.some(s=>s.type==='hand')")
  await page.evaluate("()=>{const o=sceneStore.getState().scene.objects.find(o=>o.id===objectId),origin=xrStore.getState().origin.position;window.beforeHand=JSON.parse(JSON.stringify(o));device.hands.right.position.set(o.position[0]-origin.x,o.position[1]-origin.y,o.position[2]-origin.z);device.hands.right.quaternion.set(0,0,0,1);window.pastBefore=sceneStore.getState().past.length}")
  await page.wait_for_timeout(1500);await page.evaluate('device.hands.right.updatePinchValue(1)');await page.wait_for_timeout(1500);await page.evaluate('device.hands.right.position.x+=0.5');await page.wait_for_timeout(1200);await page.evaluate('device.hands.right.updatePinchValue(0)');await page.wait_for_timeout(1800)
  change=await page.evaluate("({before:beforeHand,after:sceneStore.getState().scene.objects.find(o=>o.id===objectId),pastDelta:sceneStore.getState().past.length-pastBefore})")
  print('Hand move:',change);assert abs(change['after']['position'][0]-change['before']['position'][0]-0.5)<0.05 and change['pastDelta']==1
  # Two tracked controller pointers rotate and uniformly scale the same chair.
  await page.evaluate("device.primaryInputMode='controller'")
  await page.wait_for_timeout(2500)
  await page.evaluate("()=>{const o=sceneStore.getState().scene.objects.find(o=>o.id===objectId),origin=xrStore.getState().origin.position;window.twoBefore=JSON.parse(JSON.stringify(o));window.pastBefore=sceneStore.getState().past.length;window.center={x:o.position[0]-origin.x,y:o.position[1],z:o.position[2]-origin.z};device.controllers.left.position.set(center.x-0.15,center.y,center.z);device.controllers.right.position.set(center.x+0.15,center.y,center.z);device.controllers.left.quaternion.set(0,0,0,1);device.controllers.right.quaternion.set(0,0,0,1)}")
  await page.wait_for_timeout(1600)
  await page.evaluate("device.controllers.right.updateButtonValue('squeeze',1)")
  await page.wait_for_timeout(800)
  await page.evaluate("device.controllers.left.updateButtonValue('squeeze',1)")
  await page.wait_for_timeout(1000)
  await page.evaluate("device.controllers.left.position.set(center.x-0.3,center.y,center.z);device.controllers.right.position.set(center.x+0.3,center.y,center.z)")
  await page.wait_for_timeout(1800)
  await page.evaluate("device.controllers.left.position.set(center.x,center.y,center.z+0.3);device.controllers.right.position.set(center.x,center.y,center.z-0.3)")
  await page.wait_for_timeout(1800)
  await page.evaluate("device.controllers.left.updateButtonValue('squeeze',0)")
  await page.wait_for_timeout(600)
  await page.evaluate("device.controllers.right.updateButtonValue('squeeze',0)")
  await page.wait_for_timeout(2000)
  transformed=await page.evaluate("({before:twoBefore,after:sceneStore.getState().scene.objects.find(o=>o.id===objectId),pastDelta:sceneStore.getState().past.length-pastBefore})")
  print('Two-pointer transform:',transformed)
  ratio=transformed['after']['scale'][0]/transformed['before']['scale'][0];assert 1.8<ratio<2.1;assert abs(transformed['after']['rotationY']-transformed['before']['rotationY']-math.pi/2)<0.1;assert transformed['pastDelta']==1;print('PASS two-controller uniform scale and yaw rotation')
  await page.screenshot(path=str(ROOT/'hands.png'),timeout=90000)
  # Headset board buttons are exercised with the actual controller ray/trigger.
  await page.evaluate("""()=>{window.aimKey=(label)=>{const root=xrStore.getState().origin;let text;root.traverse(o=>{if(o.text===label.toUpperCase())text=o});if(!text)throw Error('Missing key '+label);const point=text.getWorldPosition(text.position.clone()),origin=root.position;device.controllers.right.position.set(point.x-origin.x,point.y-origin.y,point.z-origin.z+0.35);device.controllers.right.quaternion.set(0,0,0,1);device.controllers.left.position.set(-3,1.3,-0.3)}}""")
  count=await page.evaluate('sceneStore.getState().scene.objects.length')
  await page.evaluate("aimKey('Objects')");await page.wait_for_timeout(1400)
  await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(500)
  await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(2500)
  await page.evaluate("aimKey('Chair')");await page.wait_for_timeout(1400)
  await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(500)
  await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(2500)
  assert await page.evaluate('sceneStore.getState().scene.objects.length')==count+1
  print('PASS in-headset catalog placement via controller ray')
  await page.evaluate("aimKey('Spatial / performance')");await page.wait_for_timeout(1200)
  await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(400);await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(1800)
  await page.evaluate("aimKey('Manual floor')");await page.wait_for_timeout(1000);await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(400);await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(1500)
  await page.evaluate("aimKey('Save alignment')");await page.wait_for_timeout(1000);await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(400);await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(1500)
  assert await page.evaluate('sceneStore.getState().scene.alignment.length>0')
  await page.evaluate("aimKey('HUD off')");await page.wait_for_timeout(1000);await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(400);await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(1500)
  await page.screenshot(path=str(ROOT/'spatial-hud.png'),timeout=90000)
  await page.evaluate("aimKey('Close')");await page.wait_for_timeout(1000);await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(400);await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(1500)
  await page.evaluate("aimKey('Save')");await page.wait_for_timeout(1000);await page.evaluate("device.controllers.right.updateButtonValue('trigger',1)");await page.wait_for_timeout(400);await page.evaluate("device.controllers.right.updateButtonValue('trigger',0)");await page.wait_for_timeout(1500)
  print('PASS spatial controls, relative metadata, HUD and local save through rendered controller targets')
  await page.evaluate("device.primaryInputMode='hand';sceneStore.getState().setGazePinch(true);device.hands.left.position.set(-3,1.3,-0.3);device.hands.right.position.set(0.25,1.3,-0.25)");await page.wait_for_timeout(2000)
  await page.evaluate("()=>{window.aimHead=label=>{let text;xrStore.getState().origin.traverse(o=>{if(o.text===label.toUpperCase())text=o});if(!text)throw Error('Missing '+label);const point=text.getWorldPosition(text.position.clone()),origin=xrStore.getState().origin.position;device.position.set(point.x-origin.x,point.y-origin.y,point.z-origin.z+1.05);device.quaternion.set(0,0,0,1)}}")
  await page.evaluate("aimHead('Spatial / performance')");await page.wait_for_timeout(1600)
  await page.evaluate('device.hands.right.updatePinchValue(1)');await page.wait_for_timeout(700);await page.evaluate('device.hands.right.updatePinchValue(0)');await page.wait_for_timeout(2000)
  assert await page.evaluate("(()=>{let found=false;xrStore.getState().origin.traverse(o=>{if(o.text==='MANUAL FLOOR')found=true});return found})()")
  print('PASS hysteresis head-directed EMULATED right-hand pinch opens spatial controls')
  await page.screenshot(path=str(ROOT/'head-pinch.png'))
  await page.evaluate("aimHead('Close')");await page.wait_for_timeout(1600);await page.evaluate('device.hands.right.updatePinchValue(1)');await page.wait_for_timeout(700);await page.evaluate('device.hands.right.updatePinchValue(0)');await page.wait_for_timeout(1500)
  saved=await page.evaluate('JSON.stringify(sceneStore.getState().scene)')
  await page.evaluate('xrStore.getState().session.end()');await page.get_by_text('Immersive session running',exact=True).wait_for(state='hidden');await page.wait_for_timeout(2000)
  assert saved==await page.evaluate('JSON.stringify(sceneStore.getState().scene)')
  await page.goto('http://localhost:8080/studio');await page.wait_for_timeout(6000)
  await page.evaluate('async s=>window.sceneStore=(await import(s)).useStudio',modules['scene'])
  assert json.loads(saved)==await page.evaluate('sceneStore.getState().scene')
